class Produk{
    public string ID, Name, Tag, Description, Price, Quantity;
    public List<Rating> Ratings;

    public Produk(){}

    public Produk(string ID, string Name, string Tag, string Description, 
                 float Price, int Quantity, List<Rating> Ratings){
        this.ID = ID;
        this.Name = Name;
        this.Tag = Tag;
        this.Description = Description;
        this.Price = Price.ToString();
        this.Quantity = Quantity.ToString();
        this.Ratings = Ratings;
    }

    // Compare loop over all required fields and detect changed values
    public bool AreEqual(Produk other){
        if(this == null && other != null)return false;

        return Equals(ID, other.ID) &&
               Equals(Name, other.Name) &&
               Equals(Tag, other.Tag) &&
               Equals(Description, other.Description) &&
               Equals(Price, other.Price) &&
               Equals(Quantity, other.Quantity);
    }
}

