        this.UserID = userID;
        this.ProductID = productID;
        this.ReviewText = reviewText;
        this.StarCount = starCount.ToString();
        this.AverageStar = averageStar.ToString();
    }

    public override string ToString() => $"{UserID} {ProductID} {ReviewText}";
}

