/**
 * Simple example of a script
 * which will calculate revenue after discount.
 * @param float|int $cost Total cost before discounts
 * @return float|false Result after applied discount
 */
function apply_discount(float $cost): float|false {

    // Check if the input is valid
    if (!is_float($cost) || $cost < 0) {
        return false;
    }

    // Define the discount percentage
    const DISCOUNT = 0.2; 

    // Apply the discount and return the result
    return $cost * (1 - $DISCOUNT);
}

// Example usage
$original_price = 50;
$discounted_price = apply_discount($original_price);

echo "Original price: \$" . number_format($original_price, 2, '.', ',');
echo "\nDiscounted price: \$" . number_format($discounted_price, 2, '.', ',');
