﻿using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace MonoListingExperiment
{
    public class BalancingPair<T>
    {
        private readonly Dictionary<T, int> _pairs;
        private int _count;

        public void Add(T item)
        {
            _pairs.TryAdd(item, _count++);
            _pairs[item] = _count;
        }

        public bool Contains(int count) => _pairs.Values.Contains(count);
    }

    public class SymbolTree<T>
    {
        public T[] Array { get; set; }
        public T CurrentValue { get; set; } = default!;
        public string[] Children { get; set; } = null!;

        public void Init(string[] array)
        {
            foreach (var element in array)
                Add(element);
        }

        public void Add(T item)
        {
            if (CurrentValue == default!)
            {
                CurrentValue = item;
            }

            else
            {
                var left = Array[0];
                var right = Array[1];

                if (item < left && item < right)
                    Left.Array = Array;
                else if (item > left && item > right)
                    Right.Array = Array;
            }
        }

        public override string ToString()
        {
            return $"{CurrentValue}";
        }
    }

    internal class Program
    {
        static void Main(string[] args)
        {
            List<int> selectedValues = new List<int>(60);

            Random random = new Random();

            // Sample 60 distinct integers
            for (int i = 0; i < 60; i++)
            {
                selectedValues.Add(random.Next(100));
            }

            Graph(_selectedValues);
        }

        static void Graph(List<int> values)
        {
            var graph = new Dictionary<string, LinkedList<int>>();
            var queue = new Queue();

            foreach (var val in values)
            {
                var key = $"-{val}";

                if (!graph.ContainsKey(key))
                    graph[key] = new LinkedList<int>();

                graph[key].AddLast(val);
                queue.Enqueue(val);
            }

            while (queue.Count > 0)
            {
                int currentVal = queue.Dequeue();
                string key = $"-{currentVal}";

                if (graph.TryGetValue(key, out var linkedList))
                {
                    if (linkedList.Count <= 1)
                        continue;

                    int next = random.Next(linkedList.Count);

                    queue.Enqueue(linkedList.ElementAt(next));

                    linkedList.RemoveAt(next);
                }
            }

            Console.WriteLine("Initial Data:");
            PrintData(values);

            var result = new List<(string, int)>();
            var baseGraph = new Dictionary<string, LinkedList<int>>();

            foreach (var pair in graph)
            {
                var childrenKey = $"{pair.Key.Replace('-', '')}-children";
                if (!baseGraph.ContainsKey(childrenKey))
                    baseGraph[childrenKey] = new LinkedList<int>();

                foreach (var child in pair.Value)
                {
                    baseGraph[childrenKey].AddLast(child);
                }
            }

            ShowAllGraph(baseGraph, $"{values[0]}", "");
        }

        static void PrintData(List<int> list)
        {
            foreach (var val in list)
            {
                Console.WriteLine(val);
            }
        }

        static void ShowAllGraph(Dictionary<string, LinkedList<int>> graph, string rootName, string prefix)
        {
            var buffer = new StringBuilder(prefix);
            buffer.Append(rootName).Append('.');
            if (graph.TryGetValue(buffer.ToString(), out var children))
            {
                if (children.Count > 0)
                {
                    buffer.Append("{");
                    buffer.AppendLine("");

                    foreach (var child in children)
                    {
                        buffer.Append(child.ToString());
                        buffer.AppendLine("");
                    }

                    buffer.AppendLine("}");
                }
            }

            foreach (var child in graph.Keys)
            {
                if (child != rootName && child.StartsWith(rootName))
                {
                    ShowAllGraph(graph, child, buffer.ToString());
                }
            }
        }
    }
}




